require 'C:/xampp/htdocs/boticav1/config/database.php';require __DIR__.'/../integration/payroll/api/payroll.php';$db=appPdoConnection();$db->beginTransaction();$q=$db->query("SELECT p.*,pp.Sueldo SueldoConfigurado,e.DniRuc FROM Rhu_PlanillaPeriodo p JOIN Rhu_PlanillaPersonal pp ON pp.IdEmpleado=p.IdEmpleado JOIN Rhu_Empleado e ON e.IdEmpleado=p.IdEmpleado WHERE p.IdPlanilla=1 FOR UPDATE");$before=$q->fetch(PDO::FETCH_ASSOC);if(!$before||$before['DniRuc']!=='73604150'||$before['Periodo']!=='2026-10'||(float)$before['SueldoConfigurado']!==1130.0||(float)$before['Neto']!==500.0){$db->rollBack();throw new Exception('Record differs; no correction made');}$old=json_decode($before['Detalle'],true);if((float)$old['Sueldo']!==500.0||(float)$old['Descuentos']!==0.0){$db->rollBack();throw new Exception('Unexpected salary calculation');}
$q=$db->query("SELECT pg.*,cb.Anulado CajaAnulado FROM Rhu_PlanillaPago pg JOIN Cb_CajaBanco cb ON cb.IdCajaBanco=pg.IdCajaBanco WHERE pg.IdPlanilla=1");$payments=$q->fetchAll(PDO::FETCH_ASSOC);$paid=0;foreach($payments as $p)if(!$p['Anulado']&&!$p['CajaAnulado'])$paid+=(float)$p['Importe'];if(count($payments)!==1||$payments[0]['Tipo']!=='ADELANTO'||$paid!==500.0){$db->rollBack();throw new Exception('Payments differ');}
file_put_contents(__DIR__.'/../.tmp-fiorela-salary-before.json',json_encode(['period'=>$before,'payments'=>$payments,'reason'=>'User confirmed monthly salary 1130, advance 500 was mistakenly used as period salary','corrected_at'=>date('c')],JSON_PRETTY_PRINT));
$old['Sueldo']=1130;$detail=nstPayrollTotals($old);if($detail['Neto']!==1130.0)throw new Exception('Unexpected corrected net');$s=$db->prepare('UPDATE Rhu_PlanillaPeriodo SET Detalle=?,Neto=? WHERE IdPlanilla=1 AND Neto=500');$s->execute([json_encode($detail,JSON_UNESCAPED_UNICODE),$detail['Neto']]);if($s->rowCount()!==1)throw new Exception('Update count differs');$db->commit();echo "Salary restored: 1130. Advance preserved: 500. Remaining: 630. No cash movement changed or created.\n";
